result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_impulse.py", "content": """"Tests for impulse.resolve.

Regression test: kinetic energy must never increase across a collision.
Property test: linear momentum is conserved for any masses and restitution.
"""

import pytest

from impulse import kinetic_energy, resolve

# Head-on approach cases: (va, vb, ma, mb) with bodies moving toward each other.
HEAD_ON_CASES = [
    (5.0, -5.0, 1.0, 1.0),    # equal masses
    (3.0, 0.0, 2.0, 2.0),     # one body ramming a resting twin
    (10.0, -1.0, 0.5, 3.0),   # light fast vs heavy slow
    (-4.0, 7.0, 5.0, 1.0),    # heavy from the left
]

MASS_E_GRID = [
    (ma, mb, e)
    for ma in (0.5, 1.0, 4.0)
    for mb in (0.25, 2.0, 8.0)
    for e in (0.0, 0.3, 0.7, 1.0)
]


class TestEnergyNonIncreasing:
    """Regression: e=1 head-on collisions used to GAIN energy (sign bug)."""

    @pytest.mark.parametrize("va,vb,ma,mb", HEAD_ON_CASES)
    def test_elastic_head_on_does_not_gain_energy(self, va, vb, ma, mb):
        ke_before = kinetic_energy(va) * ma + kinetic_energy(vb) * mb
        va2, vb2 = resolve(va, vb, ma, mb, e=1.0)
        ke_after = kinetic_energy(va2) * ma + kinetic_energy(vb2) * mb
        assert ke_after <= ke_before + 1e-9

    def test_equal_mass_elastic_swaps_velocities(self):
        # Canonical elastic bounce: identical masses exchange velocities.
        assert resolve(5.0, -3.0, 1.0, 1.0, e=1.0) == pytest.approx((-3.0, 5.0))


class TestMomentumConservation:
    """Property: total momentum is invariant for any masses and e in [0, 1]."""

    @pytest.mark.parametrize("ma,mb,e", MASS_E_GRID)
    def test_momentum_is_conserved(self, ma, mb, e):
        va, vb = 2.0, -6.0
        p_before = ma * va + mb * vb
        va2, vb2 = resolve(va, vb, ma, mb, e)
        p_after = ma * va2 + mb * vb2
        assert p_after == pytest.approx(p_before)

    @pytest.mark.parametrize("ma,mb,e", MASS_E_GRID)
    def test_restitution_dissipates_energy(self, ma, mb, e):
        va, vb = 4.0, -2.0
        ke_before = ma * kinetic_energy(va) + mb * kinetic_energy(vb)
        va2, vb2 = resolve(va, vb, ma, mb, e)
        ke_after = ma * kinetic_energy(va2) + mb * kinetic_energy(vb2)
        if e < 1.0:
            assert ke_after < ke_before + 1e-9
        else:
            assert ke_after <= ke_before + 1e-9
